bool isValid(std::string s) {
    std::stack<char> stk;
    std::unordered_map<char,char> m = {{')', '('}, {'}', '{'}, {']', '['}};
    for (char ch : s) {
        if (m.count(ch)) {
            char top = stk.empty() ? '#' : stk.top();
            if (!stk.empty()) stk.pop();
            if (m[ch] != top) return false;
        } else {
            stk.push(ch);
        }
    }
    return stk.empty();
}

