        if r < 0 || r >= rows || c < 0 || c >= cols { return; }
        if grid[r as usize][c as usize] != '1' { return; }
        grid[r as usize][c as usize] = '0';
        for (dr, dc) in [(1,0),(-1,0),(0,1),(0,-1)] {
