def majority_element(nums: list[int]) -> list[int]:
    k = 3
    n = len(nums)
    cnts: dict[int, int] = {}

    for i in nums:
        cnts[i] = cnts.get(i, 0) + 1
        if len(cnts) == k:
            for j in list(cnts.keys()):
                cnts[j] -= 1
                if cnts[j] == 0:
                    del cnts[j]

