std::vector<int> majorityElement(std::vector<int>& nums) {
    int k = 3;
    int n = nums.size();
    std::unordered_map<int, int> hash;

    for (int i : nums) {
        hash[i]++;
        if ((int)hash.size() == k) {
            for (auto it = hash.begin(); it != hash.end(); ) {
                if (--(it->second) == 0) {
                    it = hash.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    for (auto& it : hash) {
        it.second = 0;
    }

    for (int i : nums) {
        auto it = hash.find(i);
        if (it != hash.end()) {
            it->second++;
        }
    }

    std::vector<int> ret;
    for (auto& it : hash) {
        if (it.second > n / k) {
            ret.push_back(it.first);
        }
    }
    std::sort(ret.begin(), ret.end());
    return ret;
}

