def num_subarray_product_less_than_k(nums: list[int], k: int) -> int:
    if k <= 1:
        return 0
    result, start, prod = 0, 0, 1
    for i, num in enumerate(nums):
        prod *= num
        while prod >= k:
            prod //= nums[start]
            start += 1
        result += i - start + 1
    return result

