def longest_subarray(nums: list[int]) -> int:
    count, left = 0, 0
    right = 0
    for right in range(len(nums)):
        count += (nums[right] == 0)
        if count >= 2:
            count -= (nums[left] == 0)
            left += 1
    return (right - left + 1) - 1

