fn longest_subarray(nums: &[i32]) -> i32 {
    let mut count: i32 = 0;
    let mut left: usize = 0;
    let mut right: usize = 0;
    for r in 0..nums.len() {
        right = r;
        count += (nums[r] == 0) as i32;
        if count >= 2 {
            count -= (nums[left] == 0) as i32;
            left += 1;
        }
    }
    (right as i32 - left as i32 + 1) - 1
}

