int minSubArrayLen(int s, std::vector<int>& nums) {
    int start = -1, sum = 0, min_size = std::numeric_limits<int>::max();
    for (int i = 0; i < (int)nums.size(); ++i) {
        sum += nums[i];
        while (sum >= s) {
            min_size = std::min(min_size, i - start);
            sum -= nums[++start];
        }
    }
    if (min_size == std::numeric_limits<int>::max()) {
        return 0;
    }
    return min_size;
}

