fn min_sub_array_len(s: i32, nums: &[i32]) -> i32 {
    let mut start: i32 = 0;
    let mut sum: i32 = 0;
    let mut min_size = i32::MAX;
    for i in 0..nums.len() {
        sum += nums[i];
        while sum >= s {
            min_size = min_size.min(i as i32 - start + 1);
            sum -= nums[start as usize];
            start += 1;
        }
    }
    if min_size == i32::MAX { 0 } else { min_size }
}
